function filtered(){let list=state.sources.filter(s=>(scope==='archived'?s.annotation.archived:!s.annotation.archived)&&(!author||s.author===author)&&(!kind||s.kind===kind)&&(!tag||s.annotation.tags.includes(tag))&&(!folder||s.annotation.folder===folder)&&(!status||(status==='text'?s.segment_count>0:status==='missing'?s.segment_count===0:s.annotation.state===status))&&(scope!=='liked'||s.annotation.liked)&&(!query||(sourceSearchIds?sourceSearchIds.has(s.id):norm(s.title+' '+s.author+' '+s.annotation.tags.join(' ')).includes(norm(query)))));list.sort((a,b)=>sort==='added'?(b.added_at||'').localeCompare(a.added_at||''):sort==='title'?a.title.localeCompare(b.title,'fr'):sort==='duration'?b.duration-a.duration:(b.date||'').localeCompare(a.date||''));return list}
